  "경쟁 에너지를 안정적으로 담아주는 컬러입니다.": "能稳妥地承载竞争能量的颜色。",
  "경쟁성장형형제자매": "竞争成长型兄弟姐妹",
  "경쟁이 아닌 응원으로 바뀔 때, 이 관계는 서로를 가장 멀리 데려다주는 힘이 됩니다.": "当竞争转化为彼此的鼓励时，这段关系会成为把彼此带得最远的力量。",
  "경험에서 얻은 기준을 차분히 나누고, 아이가 현실에서 자기 힘을 쓸 수 있도록 돕는 역할을 맡기 쉽습니다.": "容易承担从经验中沉稳传递标准，并帮助孩子在现实中运用自身力量的角色。",
  "곁에서 응원해주는 사람이 있다는 것만으로도 더 멀리 나아갈 수 있습니다.": "只要有人在身边为你加油，就能走得更远。",
