  "다만 지금은 세이지 카드 영향으로 차분하고 지혜롭게 갈등을 바라보는 마음이 강해지는 시기입니다. 서두르지 않고 천천히 대화하는 것이 이 시기에 가장 좋습니다.": "不过现在受鼠尾草色卡片影响，可能更以冷静与智慧的心态看待冲突。不要急躁，慢慢对话，是此时最好的方式。",
  "다만 지금은 스카이블루 카드 영향으로 자유롭고 가볍게 갈등을 해소하고 싶은 마음이 높아질 수 있습니다. 무거운 대화보다 가볍게 연결하는 방식이 이 시기에 효과적입니다.": "不过现在受天蓝卡片影响，可能更想以自由轻松的方式化解冲突。与其进行沉重对话，不如以轻松连结的方式，会更有效。",
  "다만 지금은 스카이블루 카드 영향으로 자유롭고 가볍게 쉬고 싶은 마음이 높아질 수 있습니다. 부담 없이 열린 방식으로 쉬는 것이 이 시기에 좋습니다.": "不过现在受天蓝色卡片的影响，你可能更想自由轻松地休息。以无负担、开放的方式放松很适合此阶段。",
  "다만 지금은 스카이블루 카드 영향으로 자유롭고 가볍게 움직이고 싶은 마음이 높아지는 시기입니다. 부담 없이 열린 방식으로 일상을 채워가는 것이 이 시기에 잘 맞습니다.": "不过，现在受天蓝卡片的影响，你会更想自由、轻松地行动。以无负担、开放的方式充实日常，会很适合这段时间。",
  "다만 지금은 스카이블루 카드 영향으로 자유롭고 유연하게 소비하고 싶은 마음이 높아질 수 있습니다. 지나친 제약보다 합리적인 범위 안에서 유연하게 소비하는 것이 좋습니다.": "不过现在受天蓝卡影响，可能更想自由灵活地消费。与其过分约束，不如在合理范围内灵活消费比较好。",
  "다만 지금은 심리 상태가 고요하고 중립적인 시기입니다. 감정적인 반응보다 차분하게 상황을 바라보는 것이 갈등 해결에 도움이 됩니다.": "不过现在心理状态相对平静且中立。与其情绪化反应，不如冷静地审视情境，有助于解决冲突。",
  "다만 지금은 심리 상태가 고요하고 중립적인 시기입니다. 무리한 변화보다 지금의 일상 리듬을 그대로 유지하는 것이 가장 자연스럽습니다.": "不过现在心理状态较为平静且中立。与其进行剧烈改变，不如保持当前的日常节奏，这样最为自然。",
  "다만 지금은 심리 상태가 고요하고 중립적인 시기입니다. 큰 재정 결정보다 현재의 소비 패턴을 점검하고 유지하는 것이 가장 좋습니다.": "不过现在是心理状态平静且中性的时期。与其做重大的财务决定，不如检查并维持当前的消费模式最好。",
  "다만 지금은 심리 상태가 고요하고 중립적인 시기입니다. 특별한 활동보다 현재의 회복 리듬을 그대로 유지하는 것이 가장 좋습니다.": "不过现在心理状态比较平静、中性。与其做特别的活动，不如保持目前的恢复节奏。",
