  "다만 지금은 옐로우 카드 영향으로 가볍고 즐거운 소비에 대한 욕구가 높아질 수 있습니다. 소소한 즐거움을 위한 소비는 허용하되 큰 지출은 한 번 더 생각해보는 것이 좋습니다.": "不过，现在受黄色卡片的影响，你可能会更渴望轻松愉快的消费。可以允许为小确幸的消费，但在大额支出上建议再三考虑。",
  "다만 지금은 옐로우 카드 영향으로 가볍고 즐겁게 움직이고 싶은 마음이 강해지는 시기입니다. 부담 없이 일상을 밝게 채워가는 것이 이 시기에 자연스럽게 맞습니다.": "不过现在受黄色卡片影响，会更想轻松愉快地行动。无负担地让日常变得明快，在这段时间里最为自然。",
  "다만 지금은 옐로우 카드 영향으로 갈등을 가볍게 넘기거나 유머로 풀려는 마음이 강해질 수 있습니다. 상대의 감정을 먼저 확인하고 공감해주는 것이 이 시기에 중요합니다.": "不过现在受黄色卡片的影响，你可能倾向于轻松化解冲突或用幽默化解。但此时先确认对方的感受并给予共感很重要。",
  "다만 지금은 오렌지 카드 영향으로 감정 표현이 활발해지고 변화를 원하는 마음이 높아질 수 있습니다. 갈등 후 새로운 방식으로 대화를 시도해보는 것이 이 시기에 도움이 됩니다.": "不过现在受橙色卡片的影响，情绪表达会更活跃，渴望改变的心情可能增强。冲突过后尝试以新的方式对话会有帮助。",
  "다만 지금은 오렌지 카드 영향으로 새로운 경험과 변화에 돈을 쓰고 싶은 마음이 커질 수 있습니다. 예산 안에서 함께 새로운 경험을 계획하는 것이 이 시기에 잘 맞습니다.": "不过，现在受橙色卡片的影响，你可能会更想把钱花在新的体验和变化上。建议在预算内一起规划新的体验，会很适合这段时间。",
  "다만 지금은 오렌지 카드 영향으로 새로운 경험을 통해 충전하고 싶은 마음이 높아질 수 있습니다. 함께 새로운 장소나 활동을 시도해보는 것이 이 시기에 좋습니다.": "不过现在受橙色卡影响，可能更想通过新体验来充电。一起尝试新的地点或活动在此时比较合适。",
  "다만 지금은 오렌지 카드 영향으로 새로운 방식을 시도하고 싶은 마음이 평소보다 강해질 수 있습니다. 일상에 작은 변화를 하나씩 더해보는 것이 이 시기에 잘 맞습니다.": "不过现在受橙色卡片影响，想尝试新方式的意愿可能比平时更强。往日常里逐步加入小变化，这个时期很适合这样做。",
