  "다만 지금은 인디고 카드 영향으로 깊은 고독과 내면의 시간을 통해 충전하고 싶은 마음이 강해질 수 있습니다. 서두르지 않고 자신만의 방식으로 회복하는 것이 좋습니다.": "不过现在受靛蓝卡影响，可能更想通过深刻的独处与内在时光来充电。不急于行动，按自己的方式恢复会比较好。",
  "다만 지금은 인디고 카드 영향으로 깊이 생각하고 혼자 정리하려는 마음이 강해질 수 있습니다. 갈등 후 자신의 감정을 충분히 탐색한 뒤 상대와 대화하는 것이 이 시기에 좋습니다.": "不过现在受靛蓝色卡片的影响，你可能更想深入思考并独自整理情绪。冲突后充分探索自己的感受再与对方沟通较为合适。",
  "다만 지금은 인디고 카드 영향으로 생각이 많아지고 일상 속에서도 깊이 고민하게 되는 시기입니다. 서두르지 않고 자신의 속도대로 움직이는 것이 이 시기에 맞습니다.": "不过现在受靛蓝卡片影响，思绪会变多，即使在日常也会有更深的思考。不要急，按自己的节奏行动，最为合适。",
  "다만 지금은 코랄 카드 영향으로 활기차게 움직이고 싶은 마음이 강해지는 시기입니다. 이 활력을 일상 속에서 긍정적인 방향으로 표현해보세요.": "不过，现在受珊瑚卡片的影响，你可能会更想充满活力地行动。试着在日常中以积极的方式表达这种活力。",
