  "다만 지금은 코랄 카드 영향으로 활기차고 즉흥적인 소비 욕구가 강해지는 시기입니다. 이 활력을 긍정적으로 활용하되 충동 지출은 주의하는 것이 좋습니다.": "不过现在受珊瑚色卡影响，是一个活跃且即兴消费欲望增强的时期。建议将这份活力积极利用，但要注意避免冲动支出。",
  "다만 지금은 코랄 카드 영향으로 활기차고 직접적인 감정 표현 욕구가 강해지는 시기입니다. 이 마음을 긍정적인 방향으로 표현하되 상대의 속도를 배려하는 것이 중요합니다.": "不过现在受珊瑚色卡片影响，正值想以充满活力且直接的方式表达情感的时期。把这种心情以正面的方式表达，同时体谅对方的节奏，十分重要。",
  "다만 지금은 피치 카드 영향으로 따뜻한 관계를 위한 소비 욕구가 높아질 수 있습니다. 상대와 함께하는 경험에 투자하되 서로 부담 없는 수준을 유지하는 것이 좋습니다.": "不过现在受桃粉卡影响，可能更想为温暖的关系而消费。可以为与对方共同的体验投入，但保持彼此不感到负担的程度比较好。",
