  "다만 지금은 피치 카드 영향으로 부드럽고 따뜻한 방식으로 충전하고 싶은 마음이 높아질 수 있습니다. 상대와 함께하는 따뜻한 시간이 이 시기에 최고의 회복이 됩니다.": "不过现在受桃色卡片的影响，你可能更想以柔和温暖的方式补充能量。与对方共度的温暖时光是此阶段最好的恢复方式。",
  "다만 지금은 피치 카드 영향으로 부드럽고 따뜻한 일상을 원하는 마음이 높아지는 시기입니다. 상대와 함께하는 따뜻한 순간을 의도적으로 만들어보는 것이 좋습니다.": "不过，现在受蜜桃卡片的影响，你会更渴望温柔而温暖的日常。建议有意识地制造与对方共享的温馨时刻。",
  "다만 지금은 핑크 카드 영향으로 따뜻한 연결과 공감을 원하는 마음이 높아질 수 있습니다. 갈등 후 상대의 마음을 먼저 확인하고 따뜻하게 다가가는 것이 이 시기에 관계를 회복하는 가장 좋은 방법입니다.": "不过现在受粉色卡片的影响，你可能更渴望温暖的连接与共情。冲突后先确认对方的心情并温暖地靠近，是修复关系的最佳方式。",
  "다만 지금은 핑크 카드 영향으로 따뜻한 연결과 함께하는 시간을 통해 충전하고 싶은 마음이 높아질 수 있습니다. 상대와 감정을 나누는 시간이 이 시기에 최고의 회복이 됩니다.": "不过现在受粉色卡影响，可能更想通过温暖的连接与陪伴来充电。与对方分享情感的时光在此时是最好的恢复。",
