  "다만 지금은 핑크 카드 영향으로 상대와 함께하는 시간과 따뜻한 연결을 더 원하게 되는 시기입니다. 일상 속 작은 공유와 대화가 이 시기에 큰 힘이 됩니다.": "不过现在受粉红色卡片影响，会更渴望与对方共处的时间与温暖的连接。日常中的小分享与对话在这段时期会带来很大帮助。",
  "다만 지금은 화이트 카드 영향으로 감정을 정리하고 비우려는 마음이 강해질 수 있습니다. 갈등 후 각자 감정을 정리하는 시간을 갖고 다시 연결하는 것이 이 시기에 잘 맞습니다.": "不过现在受白色卡片的影响，你可能更想整理并放下情绪。冲突后各自整理情绪再重新连接，很适合这个阶段。",
  "다만 지금은 화이트 카드 영향으로 불필요한 소비를 줄이고 지출을 정리하고 싶은 마음이 강해질 수 있습니다. 꼭 필요한 것만 남기고 나머지를 덜어내는 것이 이 시기에 잘 맞습니다.": "不过，现在受白色卡片的影响，你可能会更想减少不必要的消费并整理支出。只保留必要的东西，剔除其余，会很适合这段时间。",
  "다만 지금은 화이트 카드 영향으로 비우고 정리하는 방식으로 충전하고 싶은 마음이 강해질 수 있습니다. 조용하고 단순한 환경 속에서 쉬는 것이 이 시기에 잘 맞습니다.": "不过现在受白色卡影响，可能更想通过清空与整理的方式来充电。在安静且简洁的环境中休息在此时很适合。",
