  "목표 지향성": "目标导向性",
  "목표 vs 과정 가치관 차이": "目标与过程的价值观差异",
  "목표가 분명할 때 마음이 놓이는": "目标明确时，心会踏实",
  "목표가 생기면 빠르게 몰입하는 편입니다. 어려운 상황에서도 먼저 방법을 찾고 움직입니다.": "一旦有目标就会迅速投入。即使在困难的情况下也会率先寻找办法并付诸行动。",
  "목표를 세우고 달성하는 것이 중요": "设定目标并实现很重要",
  "목표를 이루는 끈기": "实现目标的坚持力",
  "목표를 향해 바로 움직이는 힘": "直奔目标的行动力",
  "목표를 향해 적극적으로 움직이고 성취의 기쁨을 소중히 여깁니다. 자신의 실력을 차근차근 쌓아갈 때 만족을 느끼는 편입니다.": "你会积极朝目标前进，珍视成就感。一步步积累实力时，你会感到满足。",
  "목표에 닿았는지 점검하며 마무리합니다": "一边检查是否达到目标，一边完成收尾",
  "목표와 기준을 분명히 세웁니다": "明确设定目标和标准",
