  "저녁 산책 후 따뜻한 음료 나누기": "晚间散步后分享热饮",
  "저녁 식사 후 짧게 \"오늘 나한테 어떤 순간이 좋았어?\"라고 물어보세요. 일상 속 작은 대화가 두 분의 정서적 연결을 유지해줍니다.": "饭后简短问一句\"今天有什么瞬间让你觉得好？\"日常里的小对话能维系你们的情感连接。",
  "저녁 식사 후 짧게 \"오늘 있었던 일 중 가장 기억나는 것\" 하나씩 나눠보세요. 오래된 관계일수록 일상의 작은 이야기가 정서적 연결을 유지해줍니다.": "晚餐后简短地各说一件“今天发生的、最让人记得的事”。关系越久，日常的小故事越能维持情感的连接。",
  "저녁에 잔잔한 음악 틀어놓고 쉬기": "晚上放些轻柔的音乐放松一下",
  "적극적인 쪽은 \"왜 나만 연락해?\"라고 느끼고, 조용한 쪽은 \"왜 이렇게 부담스럽게 하지?\"라고 느낄 수 있습니다.": "主动的一方可能会觉得“为什么只有我在联系？”，安静的一方可能会觉得“为什么要这样让人感到负担？”",
  "적당한 거리가 관계를 더 오래 유지하게 합니다. 이 관계는 그 균형을 찾아가고 있습니다.": "适度的距离让关系维持更久。这段关系正在找到那种平衡。",
  "적당한 거리가 이 관계를 더 건강하게 만드는 흐름입니다.": "适度的距离是让关系更健康的动态。",
  "적당한 거리가 이 관계를 더 오래, 더 건강하게 유지하게 합니다.": "适度的距离能让这段关系更长久、更健康。",
