  "정리": "整理",
  "정리 기준": "整理标准",
  "정리 기준이 다를 수 있지만 두 사람 모두 조용한 편이라 큰 충돌없이 대화로 해결됩니다.": "整理标准可能不同，但双方都比较安静，能够通过对话在不发生大冲突的情况下解决。",
  "정리 능력": "整理能力",
  "정리 스타일": "整理风格",
  "정리 의욕": "整理意愿",
  "정리가 될 때까지 대화를 잠시 미루는 편": "我倾向于把对话暂时搁置，直到理清为止",
  "정리되면 말함 (침묵이 길어짐)": "想明白了才说（沉默会变长）",
  "정리된 공간에서 안정감을 느낌": "在整洁的空间中感到安心",
  "정리된 공간이 집중력에 영향": "整理好的空间会影响专注力",
  "정리된 뒤 \"괜찮아?\" 짧게 묻기": "情绪整理后简短地问一句\"你还好吗？\"",
  "정리된 말과 편안한 분위기로": "以清晰的表达和舒适的氛围",
  "정리된 환경과 감정 비움이 안정감의 기반입니다": "整洁的环境与情感的放下构成安全感的基础",
  "정리된 후 함께 짧게 이야기하기": "整理好之后一起短暂聊几句",
  "정리와 거리두기를 중요하게 여기는 사람과 따뜻한 연결을 원하는 사람이 만났습니다. 한 사람은 감정이 복잡해지면 혼자 정리하려 하고, 다른 사람은 그 거리감이 서운하게 느껴집니다. \"왜 혼자 있으려 해?\"와 \"왜 이렇게 붙어 있으려 해?\"가 교차할 수 있습니다. 서로의 회복 방식이 다를 뿐, 두 사람 모두 관계를 소중히 여기고 있습니다.": "重视整理与保持距离的人，与渴望温暖连接的人相遇。一个人在情绪复杂时倾向独自整理，另一个会因这种距离感而感到委屈。会有“为什么想独自待着？”与“为什么总是黏着我？”交错的时刻。只是恢复方式不同，两人都很珍惜这段关系。",
  "정리와 명료함을 중요하게 여기는 사람과 즉각적이고 빠르게 반응하는 사람이 만났습니다. 한 사람은 감정을 혼자 정리하려 하고, 다른 사람은 지금 당장 표현하고 싶어 합니다. 청소·정리 방식이나 생활 기준의 차이가 반복적인 긴장 포인트가 될 수 있습니다.": "重视整理与明晰的人，与即时且快速反应的人相遇。一个人倾向独自整理情绪，另一个则想立刻表达。清洁·整理方式或生活标准的差异可能成为反复出现的紧张点。",
  "정리와 비움": "整理与放下",
  "정리의 말이 따뜻한 반응으로 닿도록 돕는 연결의 컬러입니다.": "这是帮助把整理的话语以温暖的回应传达出去的连接色彩。",
  "정리하는 편입니다. 생각이 가라앉은 뒤": "比较会整理。等思绪平静下来之后",
