  "조용하고 따뜻한 휴식의 에너지를 더해줍니다.": "增添安静温暖的休憩能量。",
  "조용하고 안정된 것을 좋아하며, 감정을 섬세하게 느끼는 성향이 있습니다.\n자신을 위한 부드러운 휴식과 돌봄의 시간이 필요합니다.": "你喜欢安静稳定，敏感地感受情绪。\n需要为自己留出温柔休息与呵护的时光。",
  "조용하고 안정된 것을 좋아하지만, 마음 한편에서는 더 넓은 세상으로 나아가고 싶은 마음도 있습니다.\n갈등을 피하려다 보니 하고 싶은 말을 삼키는 경우가 많습니다.": "喜欢安静与稳定，但内心一角也希望走向更广阔的世界。\n因为想避免冲突，常常会把想说的话咽下。",
  "조용하고 안정된 곳에 머물고 싶은 마음이 있습니다.\n자신을 위한 부드러운 휴식과 돌봄의 시간이 필요합니다.": "想待在安静稳定的地方。\n需要为自己留出温柔的休息与照料时间。",
  "조용하고 안정된 곳에 머물고 있는 시기입니다.\n마음을 정리하고 싶은 마음이 강하지만, 외부와의 연결이 조금 줄어들고 있습니다.\n가벼운 연결을 통해 생기를 더하는 것도 도움이 됩니다.": "这是一个待在安静稳定的阶段。\n你很想理清心绪，但与外界的联系有些减少。\n通过轻松的互动增加些活力也会有帮助。",
  "조용하고 안정된 방식으로 마무리합니다": "以安静稳定的方式收尾",
  "조용하고 편안한 분위기에서 마음을 엽니다": "在安静舒适的氛围中敞开心扉",
  "조용한 공간에서 업무 아이디어 깊이 나누기": "在安静的空间深入交流工作想法",
  "조용한 공간에서 함께 있는 시간, 의미 있는 대화, 신뢰가 쌓이는 경험이 두 사람을 연결합니다. 말이 많지 않아도 옆에 있는 것만으로 연결감을 느끼는 흐름이 이 관계의 자연스러운 방식입니다.": "在安静的空间里一起相处的时间、有意义的对话、能积累信任的经历，会把两人连结在一起。即便不多言，仅仅相伴就能感到连结，这是这段关系的自然方式。",
  "조용한 공간에서 함께 있는 시간이 두 사람을 연결합니다. 말이 많지 않아도 옆에 있는 것만으로 연결감을 느끼는 흐름이 이 관계의 자연스러운 방식입니다.": "安静地在一起的时光会把两人连结起来。即便不多言，仅凭在身边就能感到连接，这是这段关系的自然方式。",
  "조용한 공감": "静静的共情",
