  "조용한 카페에서 각자 원하는 것 하기": "在安静的咖啡馆各自做想做的事",
  "조용한 카페에서 각자 작업하거나 독서하기": "在安静的咖啡馆各自工作或阅读",
  "조용한 카페에서 각자 작업하기": "在安静的咖啡馆各自工作",
  "조용한 카페에서 깊은 주제로 대화 나누기": "在安静的咖啡馆深入交谈",
  "조용한 카페에서 차 한 잔 나누기": "在安静的咖啡馆里共享一杯茶",
  "조용한 카페에서 책 읽거나 각자 작업하기": "在安静的咖啡馆读书或各自工作",
  "조용한 평온을 지키는": "守护静谧的平和",
  "조용한 표현": "安静表达",
  "조용한 표현|내면 처리 후 표현": "安静表达|内心整理后表达",
  "조용한 호흡 또는 마음 정리 시간": "静心呼吸或整理思绪的时间",
  "조용한 회복력": "安静的恢复力",
  "조용히 감정을 비워내는 사람과 감정에 깊이 몰입하는 사람이 만났습니다. 한 사람은 거리를 두며 정화하려 하고, 다른 사람은 그 거리감이 상처로 느껴집니다. 감정 정리 방식의 차이가 반복적인 오해를 만들 수 있습니다.": "安静地释放情绪的人，与深度沉浸情感的人相遇。一个人通过保持距离来净化情绪，另一个则会把那种距离感视为伤害。情绪整理方式的差异可能反复产生误解。",
  "조용히 감정을 정리하며 진정성 있게 연결되는": "静静整理情绪，并真诚地建立连接",
  "조용히 곁에 있어 주는 관계를 소중히 여깁니다": "珍视那些静静陪伴在身边的关系",
  "조용히 곁을 지키며 마음을 살피는": "静静守在身旁，体察内心",
  "조용히 곁을 지키며 마음을 살핍니다": "静静守在身边，留心对方的心情",
  "조용히 닫혀 있던 마음을\n천천히 다시 열어보세요.": "为那颗安静地关闭着的心\n慢慢再打开看看吧。",
  "조용히 마음을 돌아보고, 그날 중요했던 한 가지를 글이나 대화로 남길 때 회복의 방향이 또렷해질 수 있습니다. 둘 다 편안하다면 그 한 문장을 서로 나눠보세요.": "安静地反思心情，把当天重要的一件事以文字或对话记录下来，会让恢复方向更明确。如果双方都觉得舒适，可以互相分享那一句话。",
  "조용히 마음이 놓이는 공간에서 잠시 쉬어보세요.": "在让心安宁的空间里静静休息片刻吧。",
  "조용히 성장하고 있는 자신을 느끼고 있을 것입니다.\n그 속도가 느려도 괜찮습니다.": "你会感受到自己在静静成长。\n即便这个速度很慢，也没关系。",
  "조용히 안정을 유지하려 애써온 시기입니다.": "这是默默努力保持稳定的时期",
  "조용히 옆에 있기": "静静地待在一旁",
  "조용히 옆에 있어주기": "静静地陪在身边",
  "조용히 옆에 있어주는 것, 말 없이 함께 있는 시간이 이 우정의 연결 방식입니다.": "默默地陪在身旁、无言相处的时光是这段友谊的连接方式。",
  "조용히 자신을 돌보며 쉬고 싶은 마음이 있습니다.\n지금 가장 필요한 것은 부드러운 휴식과 자신을 돌보는 시간입니다.": "想安静地照顾自己、好好休息。\n现在最需要的是温柔的休息和照顾自己的时间。",
  "조용히 자신을 유지하며 관계에서도 여유를 찾습니다": "静静地保持自我，并在关系中寻找从容",
