  "질서 방식이 달라 \"왜 이렇게 어질러?\"와 \"왜 이렇게 새 것을 자꾸 사?\"가 반복될 수 있습니다.": "整理方式不同，可能会反复出现\"为什么这样弄得乱？\"和\"为什么总是买新东西？\"。",
  "집 근처 단골 카페에서 조용한 시간 보내기": "在家附近常去的咖啡馆度过安静时光",
