  "활기차게 연결되고 나누고 싶은 마음이 크지만, 지금은 너무 많이 쏟아내어 자신을 돌볼 여유가 없습니다.\n자신을 먼저 채워야 주변에도 더 따뜻하게 나눌 수 있습니다.": "很想充满活力地连接与分享，但现在倾注太多，无法顾及自己。\n先充盈自己，才能更温暖地与周围分享。",
  "활기차게 연결되고 싶은 마음이 있지만, 지금은 타인을 위해 많이 쓰며 자신을 소홀히 하고 있습니다.\n자신을 먼저 돌보는 시간이 필요합니다.": "虽然渴望充满活力地连接他人，但现在过多为他人付出而忽视了自己。\n需要先照顾自己的时间。",
