  "활기차고 따뜻한 성향이지만, 관계 속에서 많이 쓰다 보니 자신을 돌보지 못하는 경우가 있습니다.\n자신을 먼저 채워야 주변에도 더 따뜻하게 나눌 수 있습니다.": "你性格活泼温暖，但在人际关系中付出过多，可能忽略了自己。\n只有先充实自己，才能更温暖地回馈周围的人。",
