  "회복력": "恢复力",
  "회복력과 재연결의 힘을 유지하면서도, 갈등이 쌓이기 전에 미리 표현하고 소통하는 습관을 만들면 이 관계는 더 깊고 안정적으로 이어질 수 있습니다.": "在保持恢复力和重连力量的同时，若在矛盾积累之前养成提前表达与沟通的习惯，这段关系会更深、更稳固。",
