  "회복의 방향": "恢复方向",
  "회복이 반복되면서 지치는 패턴.\n갈등이 옵니다. 회복됩니다. 또 갈등이 옵니다.\n\"또 이 패턴이야.\" 그 피로감이 쌓입니다.\n빠른 화해를 반복하면서 근본 원인을 다루지 않으면 같은 갈등이 반복될 수 있습니다.\n\"우리 왜 항상 이 문제로 싸우지?\" — 회복의 깊이를 더해야 합니다.": "重复恢复导致疲惫的模式。\n有冲突。恢复。又有冲突。\n“又是这个模式。”那种疲惫感不断累积。\n如果只是反复快速和好而不处理根本原因，同样的冲突可能会反复出现。\n“我们为什么总是因为这个问题争吵？”— 需要加深恢复的深度。",
  "회복하는 것만큼 \"왜 이런 갈등이 반복되는지\"를 함께 이야기하는 연습이 필요합니다. 회복 후 짧게 \"다음에는 이렇게 해보자\"를 나눠보세요.": "和恢复一样，也需要练习一起讨论“为什么会重复发生这样的冲突”。恢复后简短地说一句“下次试试这样吧”。",
  "회복하는 과정에서 말이 어렵다면, 서로 원할 때 가까이 앉아 짧은 안부부터 나눠보세요. 어깨가 닿거나 손을 잡는 선택이 다시 이야기할 여유를 만들 수 있습니다.": "在恢复过程中，如果觉得难以开口，不妨在彼此都愿意时靠近坐下，先从简短的问候开始。肩膀相触或握手的选择，能为重新交谈留出空间。",
