  "흩어진 생각들을 하나의 명료한 판단으로 연결하는 것이 지금의 회복 방향입니다.\n· 최근 고민들 중 서로 연결되는 것들을 찾아 적어보세요.\n· 그 연결에서 발견한 균형 감각을 짧게 글로 써보세요.\n· 생각이 정리될 때 현실적인 방향이 보이기 시작합니다.": "将分散的想法连接成一个清晰判断，是当前的恢复方向。\n· 请写下最近的烦恼中相互关联的部分。\n· 把从这些连接中发现的平衡感简短地写下来。\n· 当想法被整理时，现实的方向会开始显现。",
