  "흩어진 열정들을 하나의 방향으로 연결하는 것이 지금의 회복 방향입니다.\n· 지금 가지고 있는 열정들이 어떻게 서로 연결되는지 적어보세요.\n· 그 연결고리에서 하나의 큰 방향을 발견해보세요.\n· 통합된 방향으로 나아갈 때 에너지가 훨씬 강해집니다.": "将分散的热情连接为一个方向，是现在的恢复方向。\n· 试着写下你当前的热情如何彼此连接。\n· 从这些连接中发现一个宏大的方向。\n· 向整合后的方向前进时，能量会大幅增强。",
  "흩어진 통찰들을 하나의 입체적 이해로 통합하는 것이 지금의 회복 방향입니다.\n· 최근 얻은 통찰들이 어떻게 서로 연결되는지 조용히 생각해보세요.\n· 그 연결에서 발견한 더 깊은 이해를 짧게 기록해보세요.\n· 통합된 통찰은 삶의 방향을 더 명확하게 만들어줍니다.": "把散乱的洞察整合为一个立体的理解，是现在的恢复方向。\n· 请静静思考最近获得的洞察如何相互连接。\n· 将在这些连接中发现的更深理解简短记录下来。\n· 整合后的洞察会让人生的方向更明确。",
